#include "fixtures/native/media_test_host.h"
/* The test host uses a 640x480, 100%-scale pane. Send window messages only to
 * this owned hidden window; the helper's acknowledged state is the oracle. */
static void volume_click(int x,int y){SendMessageW(mediaview_window(),WM_LBUTTONDOWN,MK_LBUTTON,MAKELPARAM(x,y));SendMessageW(mediaview_window(),WM_LBUTTONUP,0,MAKELPARAM(x,y));pump_media(150);}
static void volume_controls(void){
 HWND h=mediaview_window();mediaview_control(MEDIA_VOLUME,.45);pump_media(150);volume_click(600,423);
 CHECK("plus advances 45 percent to the next ten",fabs(state().volume-.5)<.001);
 volume_click(600,423);CHECK("plus advances 50 percent to 60",fabs(state().volume-.6)<.001);
 mediaview_control(MEDIA_VOLUME,.48);pump_media(150);volume_click(600,423);CHECK("plus advances 48 percent to 50",fabs(state().volume-.5)<.001);
 mediaview_control(MEDIA_VOLUME,.48);pump_media(150);volume_click(30,423);CHECK("minus moves 48 percent down to 40",fabs(state().volume-.4)<.001);
 mediaview_control(MEDIA_VOLUME,0);pump_media(150);volume_click(30,423);CHECK("minus clamps at zero",fabs(state().volume)<.001);
 mediaview_control(MEDIA_VOLUME,1);pump_media(150);volume_click(600,423);CHECK("plus clamps at 100 percent",fabs(state().volume-1)<.001);
 SendMessageW(h,WM_LBUTTONDOWN,MK_LBUTTON,MAKELPARAM(320,423));SendMessageW(h,WM_MOUSEMOVE,MK_LBUTTON,MAKELPARAM(444,423));SendMessageW(h,WM_LBUTTONUP,0,MAKELPARAM(444,423));pump_media(150);
 CHECK("slider click and drag sets intermediate volume while muted",fabs(state().volume-.75)<.015&&state().muted);
 SendMessageW(h,WM_KEYDOWN,VK_LEFT,0);pump_media(150);CHECK("slider Left selects the next lower ten",fabs(state().volume-.7)<.001);
 SendMessageW(h,WM_KEYDOWN,VK_HOME,0);pump_media(150);CHECK("slider Home selects zero",fabs(state().volume)<.001);
 SendMessageW(h,WM_KEYDOWN,VK_END,0);pump_media(150);CHECK("slider End selects full volume",fabs(state().volume-1)<.001);
 MoveWindow(h,0,0,190,480,FALSE);volume_click(72,423);CHECK("narrow pane slider reaches zero",fabs(state().volume)<.015);
 volume_click(118,423);CHECK("narrow pane slider reaches full volume",fabs(state().volume-1)<.015);MoveWindow(h,0,0,640,480,FALSE);
}
static void test_media_protocol_and_format_routing(void){CHECK("video and audio extensions are case-insensitive",media_extension(L"movie.MP4")&&media_audio_extension(L"song.OpUs")&&!media_extension(L"notes.txt")&&!media_extension(L"playlist.m3u"));CHECK("fallback is limited to unsupported source or codec",media_fallback_error(0xc00d5212)&&media_fallback_error(0xc00d36c4)&&!media_fallback_error(0xc00d36fa)&&!media_fallback_error(0x80070005)&&!media_fallback_error(0x800705b4));CHECK("URLs, devices, ADS and relative paths refused",!media_path_valid(L"https://host/media.mp4")&&!media_path_valid(L"\\\\.\\pipe\\x")&&media_path_valid(L"\\\\?\\C:\\x.mp4")&&!media_path_valid(L"C:\\x.mp4:stream")&&!media_path_valid(L"x.mp4")&&media_path_valid(L"C:\\media\\你好 😀.mp4")&&media_path_valid(L"\\\\wsl.localhost\\Ubuntu\\tmp\\video.mp4"));struct {mediap_open open;wchar_t path[64];} packet={{640,360,0,0},L"C:\\movie.mp4"};mediap_head head={MEDIAP_OPEN,(uint32_t)(sizeof(mediap_open)+(wcslen(packet.path)+1)*2),1,0};CHECK("exact bounded UTF-16 source request accepted",media_open_valid(&head,&packet));packet.path[3]=0;CHECK("embedded NUL source suffix is refused",!media_open_valid(&head,&packet));head.size--;CHECK("odd UTF-16 payload is refused",!media_open_valid(&head,&packet));mediap_frame f={1,MEDIAP_MAX_W,MEDIAP_MAX_H,0};CHECK("frame bounds accepted only within exact banks",media_frame_valid(&f));f.bank=2;CHECK("out-of-range bank rejected",!media_frame_valid(&f));f.bank=0;f.width=UINT32_MAX;CHECK("overflowing pixel dimensions rejected",!media_frame_valid(&f));}
static void test_media_mf_lazy_fallback_and_controls(void){open_fixture(L"h264_aac.mp4");CHECK("MF opens common file in actual restricted helper",wait_ready()&&state().backend==1&&state().has_video&&!state().has_audio&&state().paused&&state().muted);CHECK("helper token stays low integrity",low_token());CHECK("MF never loads libmpv",has_mpv()==0);CHECK("duration and native dimensions reported",fabs(state().duration-5)<.1&&state().width==1280&&state().height==720);SendMessageW(mediaview_window(),WM_KEYDOWN,VK_SPACE,0);pump_media(600);CHECK("Space starts advancing playback",!state().paused&&state().position>.25);SendMessageW(mediaview_window(),WM_KEYDOWN,VK_SPACE,0);pump_media(250);double position=state().position;pump_media(250);CHECK("Space pauses and position stabilizes",state().paused&&fabs(state().position-position)<.08);mediaview_control(MEDIA_SEEK,3);pump_media(350);CHECK("seek reaches requested time",fabs(state().position-3)<.2);mediaview_control(MEDIA_VOLUME,.4);pump_media(150);CHECK("volume changes acknowledged while muted",fabs(state().volume-.4)<.001&&state().muted);volume_controls();open_fixture(L"vp9_opus.webm");CHECK("unsupported codec falls back to libmpv",wait_ready()&&state().backend==2&&media_fallback_error(state().fallback_error)&&state().has_video&&!state().has_audio);CHECK("libmpv loads only in fallback helper",has_mpv()==1);mediaview_control(MEDIA_PLAY,0);pump_media(500);CHECK("fallback playback advances",state().position>.2);mediaview_suspend();pump_media(200);CHECK("suspending preview pauses audio and video",state().paused);}
static void test_media_errors_recovery_and_supersession(void){open_fixture(L"h264_aac.mp4");open_fixture(L"vp9_opus.webm");CHECK("rapid replacement only publishes latest source",wait_ready()&&state().backend==2&&state().has_video&&!state().has_audio);DWORD pid=mediaview_helper_pid();HANDLE p=OpenProcess(PROCESS_TERMINATE,FALSE,pid);CHECK("owned helper can be interrupted",p&&TerminateProcess(p,17));if(p)CloseHandle(p);pump_media(400);CHECK("helper crash becomes visible failure",state().state==MEDIAP_FAILED&&!mediaview_helper_pid());open_fixture(L"h264_aac.mp4");CHECK("next preview recovers with a fresh helper",wait_ready()&&state().backend==1);open_fixture(L"corrupt.mp4");CHECK("corrupt media fails without hanging",!wait_ready()&&state().state==MEDIAP_FAILED);wchar_t path[32768];swprintf(path,32768,L"%ls\\missing.mp4",fixtures);mediaview_open(path,1,1);CHECK("missing source is not retried through libmpv",!wait_ready()&&state().error==ERROR_FILE_NOT_FOUND&&state().backend==1&&!state().fallback_error);}
static void test_media_close_and_disabled_resources(void){open_fixture(L"vp9_opus.webm");CHECK("fallback prepared for close",wait_ready());DWORD pid=mediaview_helper_pid();mediaview_clear();pump_media(250);CHECK("Clear ends the owned process and releases source",!alive(pid)&&!mediaview_helper_pid()&&!mediaview_state(NULL));open_fixture(L"h264_aac.mp4");mediaview_clear();pump_media(350);CHECK("cancel during asynchronous launch cannot revive source",!mediaview_helper_pid()&&!mediaview_state(NULL));mediaview_stop();CHECK("stop destroys preview window",!mediaview_window());}
int wmain(int argc,wchar_t **argv){if(argc!=2)return 2;wcsncpy(fixtures,argv[1],32767);owner=CreateWindowExW(0,L"STATIC",L"Owned media acceptance",WS_OVERLAPPEDWINDOW,0,0,800,600,NULL,NULL,GetModuleHandleW(NULL),NULL);if(!owner)return 2;CHECK("client starts without engine process",!mediaview_start(owner)&&!mediaview_helper_pid());mediaview_configure(25,1);MoveWindow(mediaview_window(),0,0,640,480,FALSE);test_media_protocol_and_format_routing();test_media_mf_lazy_fallback_and_controls();test_media_errors_recovery_and_supersession();test_media_close_and_disabled_resources();DestroyWindow(owner);printf("%d passed, %d failed; 4 media selectors\n",passed,failed);return failed?1:0;}
